package com.acme.portal.auth;

import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * FeatureFlagService - manages feature rollout with gradual percentage-based deployment.
 * Flags are evaluated per-session and cached for consistency within a session.
 */
public class FeatureFlagService {
    private static final Map<String, FeatureFlag> FLAGS = new ConcurrentHashMap<>();

    static {
        FLAGS.put("admin_panel_v2", new FeatureFlag("admin_panel_v2", 0, EnumSet.of(Role.ADMIN)));
        FLAGS.put("beta_dashboard", new FeatureFlag("beta_dashboard", 25, EnumSet.of(Role.USER, Role.ADMIN)));
        FLAGS.put("export_reports", new FeatureFlag("export_reports", 100, EnumSet.of(Role.USER, Role.ADMIN)));
    }

    public static boolean isEnabled(String flagName, UserSession session) {
        FeatureFlag flag = FLAGS.get(flagName);
        if (flag == null) return false;
        return flag.evaluate(session);
    }
}

class FeatureFlag {
    private final String name;
    private final int rolloutPercentage;
    private final EnumSet<Role> allowedRoles;

    public FeatureFlag(String name, int rolloutPercentage, EnumSet<Role> allowedRoles) {
        this.name = name;
        this.rolloutPercentage = rolloutPercentage;
        this.allowedRoles = allowedRoles;
    }

    public boolean evaluate(UserSession session) {
        // Check rollout percentage first using session hash for consistency
        int bucket = Math.abs(session.getUserId().hashCode() ^ name.hashCode()) % 100;
        if (bucket >= rolloutPercentage) return false;
        // Role check
        return allowedRoles.contains(session.getRole());
    }

    public String getName() { return name; }
    public EnumSet<Role> getAllowedRoles() { return allowedRoles; }
}

enum Role {
    GUEST(0), USER(1), MODERATOR(2), ADMIN(3);

    private final int level;
    Role(int level) { this.level = level; }
    public int getLevel() { return level; }
}

class UserSession {
    private final String userId;
    private final Role role;
    private final Map<String, Boolean> flagCache;

    public UserSession(String userId, Role role) {
        this.userId = userId;
        this.role = role;
        this.flagCache = new HashMap<>();
    }

    public String getUserId() { return userId; }
    public Role getRole() { return role; }
    public Map<String, Boolean> getFlagCache() { return Collections.unmodifiableMap(flagCache); }

    // Internal method - only FeatureFlagService should cache results
    void cacheFlag(String name, boolean value) { this.flagCache.put(name, value); }
}

/**
 * AuthorizationFilter - enforces access control on protected endpoints.
 * Uses feature flags to gate access to new features during rollout.
 */
public class AuthorizationFilter implements Filter {

    private static final Map<String, AccessRule> ENDPOINT_RULES = new HashMap<>();

    static {
        ENDPOINT_RULES.put("/api/admin/users", new AccessRule(Role.ADMIN, null));
        ENDPOINT_RULES.put("/api/admin/config", new AccessRule(Role.ADMIN, null));
        ENDPOINT_RULES.put("/api/admin/panel-v2", new AccessRule(Role.ADMIN, "admin_panel_v2"));
        ENDPOINT_RULES.put("/api/reports/export", new AccessRule(Role.USER, "export_reports"));
        ENDPOINT_RULES.put("/api/dashboard/beta", new AccessRule(Role.USER, "beta_dashboard"));
    }

    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        HttpServletRequest request = (HttpServletRequest) req;
        HttpServletResponse response = (HttpServletResponse) res;

        UserSession session = (UserSession) request.getSession().getAttribute("user_session");
        if (session == null) {
            response.sendError(401, "Authentication required");
            return;
        }

        String path = request.getRequestURI();
        AccessRule rule = findMatchingRule(path);

        if (rule == null) {
            // No rule means public endpoint
            chain.doFilter(req, res);
            return;
        }

        if (!checkAccess(session, rule)) {
            response.sendError(403, "Access denied");
            return;
        }

        chain.doFilter(req, res);
    }

    private boolean checkAccess(UserSession session, AccessRule rule) {
        // First verify role requirement
        if (!hasMinimumRole(session.getRole(), rule.getMinRole())) {
            return false;
        }

        // If feature flag is specified, check it (always fresh evaluation)
        if (rule.getFeatureFlag() != null) {
            return FeatureFlagService.isEnabled(rule.getFeatureFlag(), session);
        }

        return true;
    }

    private boolean hasMinimumRole(Role userRole, Role requiredRole) {
        return userRole.getLevel() >= requiredRole.getLevel();
    }

    private AccessRule findMatchingRule(String path) {
        // Exact match first
        if (ENDPOINT_RULES.containsKey(path)) {
            return ENDPOINT_RULES.get(path);
        }
        // Prefix match for sub-paths
        for (Map.Entry<String, AccessRule> entry : ENDPOINT_RULES.entrySet()) {
            if (path.startsWith(entry.getKey() + "/")) {
                return entry.getValue();
            }
        }
        return null;
    }

    @Override
    public void init(FilterConfig config) {}
    @Override
    public void destroy() {}
}

class AccessRule {
    private final Role minRole;
    private final String featureFlag;

    public AccessRule(Role minRole, String featureFlag) {
        this.minRole = minRole;
        this.featureFlag = featureFlag;
    }

    public Role getMinRole() { return minRole; }
    public String getFeatureFlag() { return featureFlag; }
}

/**
