            throws ServletException, IOException {
        UserSession session = (UserSession) request.getSession().getAttribute("user_session");
        // Fail closed if there is no authenticated session (defense-in-depth,
        // avoids NullPointerException if invoked outside the filter chain).
        if (session == null) {
            response.sendError(401, "Authentication required");
            return;
        }

        String action = request.getParameter("action");

        // Feature flag already checked by filter, but verify role for defense-in-depth
        if (session.getRole() != Role.ADMIN) {
            response.sendError(403);
            return;
        }

        // Validate action before switching to avoid NullPointerException.
        if (action == null) {
            response.sendError(400, "Unknown action");
            return;
        }

        switch (action) {
            case "promote_user":
                promoteUser(request, response);
                break;
            case "system_config":
                updateConfig(request, response);
                break;
            default:
                response.sendError(400, "Unknown action");
